// Извлекаем данные из входящего сообщения
const msg = $input.first().json.message;

const chatId = String(msg.chat.id);
const userId = String(msg.from.id);
const username = msg.from.username || '';
const firstName = msg.from.first_name || '';
const text = msg.text || '';

// Команда /start - новый диалог
const isStart = text === '/start';

return [{
  json: {
    chatId,
    userId,
    username,
    firstName,
    text,
    isStart,
    timestamp: new Date().toISOString()
  }
}];

const input = $('Разбор сообщения').first().json;
const contextRow = $input.first().json;

// Парсим существующий контекст или создаем новый
let context = {
  messages: [],
  collectedData: {
    city: null,
    propertyType: null,
    rooms: null,
    budget: null,
    paymentMethod: null,
    timeline: null,
    contact: null
  },
  stage: 'greeting',
  isComplete: false
};

// Если контекст существует и не /start
if (contextRow.chat_id && !input.isStart) {
  try {
    context = JSON.parse(contextRow.context_json || '{}');
    if (!context.messages) context.messages = [];
    if (!context.collectedData) context.collectedData = {};
  } catch (e) {
    // Если JSON битый - начинаем заново
  }
}

// Добавляем новое сообщение пользователя
if (input.text && input.text !== '/start') {
  context.messages.push({
    role: 'user',
    content: input.text
  });
}

// Ограничиваем историю последними 10 сообщениями
if (context.messages.length > 10) {
  context.messages = context.messages.slice(-10);
}

// Формируем историю для AI
let conversationHistory = context.messages.map(m => 
  `${m.role === 'user' ? 'Клиент' : 'Ассистент'}: ${m.content}`
).join('\n');

// Собранные данные для промпта
const collected = context.collectedData;
let collectedInfo = '';
if (collected.city) collectedInfo += `Город/район: ${collected.city}\n`;
if (collected.propertyType) collectedInfo += `Тип: ${collected.propertyType}\n`;
if (collected.rooms) collectedInfo += `Комнат: ${collected.rooms}\n`;
if (collected.budget) collectedInfo += `Бюджет: ${collected.budget}\n`;
if (collected.paymentMethod) collectedInfo += `Оплата: ${collected.paymentMethod}\n`;
if (collected.timeline) collectedInfo += `Срок: ${collected.timeline}\n`;
if (collected.contact) collectedInfo += `Контакт: ${collected.contact}\n`;

return [{
  json: {
    ...input,
    context,
    conversationHistory,
    collectedInfo: collectedInfo || 'Пока ничего не собрано',
    isNewConversation: input.isStart || !contextRow.chat_id
  }
}];

const input = $('Подготовка контекста').first().json;
const aiResponse = $input.first().json;

// Парсим ответ AI
let parsed = {
  response: 'Извините, произошла ошибка. Попробуйте позже.',
  extracted: {},
  isComplete: false,
  isRefused: false
};

try {
  const content = aiResponse.choices[0].message.content;
  // Ищем JSON в ответе
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    parsed = JSON.parse(jsonMatch[0]);
  } else {
    // Если AI не вернул JSON, используем текст как ответ
    parsed.response = content;
  }
} catch (e) {
  // Если парсинг не удался, пробуем использовать как текст
  try {
    parsed.response = aiResponse.choices[0].message.content;
  } catch (e2) {
    // Оставляем дефолтное сообщение об ошибке
  }
}

// Обновляем контекст
let context = input.context;

// Мержим extracted данные
if (parsed.extracted) {
  for (const [key, value] of Object.entries(parsed.extracted)) {
    if (value && value !== 'null' && value !== null) {
      context.collectedData[key] = value;
    }
  }
}

// Добавляем ответ AI в историю
context.messages.push({
  role: 'assistant',
  content: parsed.response
});

// Проверяем полноту данных
const data = context.collectedData;
const isComplete = parsed.isComplete || (
  data.city && 
  data.propertyType && 
  data.budget && 
  data.timeline
);

context.isComplete = isComplete;
context.stage = isComplete ? 'complete' : 'collecting';

return [{
  json: {
    chatId: input.chatId,
    userId: input.userId,
    username: input.username,
    firstName: input.firstName,
    responseText: parsed.response,
    context,
    contextJson: JSON.stringify(context),
    isComplete,
    isRefused: parsed.isRefused || false,
    collectedData: context.collectedData
  }
}];

